/*--------------------------------------------------------------------------------------------*/
/*Define function S(n) that given a number n, returns the string "+n" if positive (or zero) and "-n" if negative, if n=+1 or -1 it returns + or - respectively*/

S(n):= block([], if (n=1) then return("+") elseif (n=-1) then return("-") elseif (n>=0) then return(vconcat("+", abs(n)))  else  return(vconcat("-", abs(n))));

/*Define function S1(n) that given a number n, returns the string "+n" if positive (or zero) and "-n" if negative (1 and -1 are treated as the other numbers)*/

S1(n):= block([], if (n>=0) then return(vconcat("+", abs(n)))  else  return(vconcat("-", abs(n))));

/*Define function SP(n) that given a number n, returns the string "n" if positive (or zero) and "(-n)" if negative*/

SP(n):= block([], if (n>=0) then return(n)  else  return(vconcat("(-", abs(n), ")")));

/*----------------------------------------------------------------------------------------------------*/



/*random coefficients of the equations*/
ordergreat(x,y);
sig_x_1:rand([-1,1]);
coef_x_1:sig_x_1*(rand(5)+ 2);
coef_x_2:rand_with_prohib(2,8,[coef_x_1]);
coef_y_1:rand_with_prohib(2,8,[coef_x_1]);
sig_y_2:rand([-1,1]);
coef_y_2:sig_y_2*rand_with_prohib(2,8,[coef_y_1,coef_x_2,coef_x_2*coef_y_1/coef_x_1]);

/*Getting the values of the x,y for the rhs*/
ta_x:rand_with_prohib(-4,4,[0]);
non_zero_1:(-coef_x_1*ta_x)/coef_y_1;
non_zero_2:(-coef_x_2*ta_x)/coef_y_2;
ta_y:rand_with_prohib(-4,4, [ta_x,0,non_zero_1,non_zero_2]);

/*forming the left eprerssion*/
exp1:coef_x_1*x+coef_y_1*y;
exp2:coef_x_2*x+coef_y_2*y;

/*Genrating the RHS*/
rhs_1:coef_x_1*ta_x + coef_y_1*ta_y;
rhs_2:coef_x_2*ta_x + coef_y_2*ta_y;

/* Generate equations 1 and 2: */
eq1:exp1=rhs_1;
eq2:exp2=rhs_2;

/*eliminate x unknown term*/
eq3:expand(coef_x_2*exp1) = rhs_1*coef_x_2;
eq4:expand(coef_x_1*exp2) = rhs_2*coef_x_1;
elim_oper1:if coeff(lhs(eq3),x) = coeff(lhs(eq4),x) then 1 else 0;
eq5:if elim_oper1=1 then eq4-eq3 else eq3+eq4;

/*eliminate y unknown term*/
y_const_eq1:abs(lcm(coef_y_1,coef_y_2)/coef_y_1);
y_const_eq2:abs(lcm(coef_y_1,coef_y_2)/coef_y_2);

eq6:expand(y_const_eq1*exp1) = rhs_1*y_const_eq1;
eq7:expand(y_const_eq2*exp2) = rhs_2*y_const_eq2;

relation_y: if coef_y_1*coef_y_2>0 then "equal" else "opposite";
operation_y:if coef_y_1*coef_y_2>0 then "substract" else "add"
prepos_y:if coef_y_1*coef_y_2>0 then "from" else "to"; 

eq8:if operation_y="substract" then eq6-eq7 else eq6+eq7;
